/* Fade in and rise by --ledup-reveal-y over the first 220px of scroll after the element's top
   enters the window (a fixed distance, so whatever is in the first screen is already in place).
   Each step starts 60px of scroll later. */
@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .ledup-reveal {
      animation: ledup-reveal-in linear both;
      animation-timeline: view();
      animation-range: entry calc(var(--ledup-reveal-step, 0) * 60px) entry calc(220px + var(--ledup-reveal-step, 0) * 60px);
    }
  }
}

@keyframes ledup-reveal-in {
  from {
    opacity: 0;
    transform: translateY(var(--ledup-reveal-y, 24px));
  }
  to {
    opacity: 1;
    transform: none;
  }
}

import type { CSSProperties, ElementType, ReactNode } from "react";
import { cn } from "@foundry/foundry-utils";
import "./ledup-reveal.css";

export interface LedupRevealProps {
  children?: ReactNode;
  /** the element to render (div by default) */
  as?: ElementType;
  /** how far it rises, in px (0 = fade only) */
  distance?: number;
  /** position in a staggered row: 0, 1, 2… each arrives 60px of scroll later */
  step?: number;
  className?: string;
}

/** Fades and lifts its content into place as it scrolls into view (CSS only). */
export function LedupReveal({ children, as: Tag = "div", distance = 24, step = 0, className }: LedupRevealProps) {
  return (
    <Tag
      className={cn("ledup-reveal", className)}
      style={{ "--ledup-reveal-y": `${distance}px`, "--ledup-reveal-step": step } as CSSProperties}
    >
      {children}
    </Tag>
  );
}
